{"command":"function Inflate-GitBytes([string]$path) {
  $bytes = [System.IO.File]::ReadAllBytes($path)
  $payload = New-Object byte[] ($bytes.Length - 6)
  [Array]::Copy($bytes, 2, $payload, 0, $payload.Length)
  $ms = New-Object System.IO.MemoryStream (,$payload)
  $ds = New-Object System.IO.Compression.DeflateStream ($ms, [System.IO.Compression.CompressionMode]::Decompress)
  $out = New-Object System.IO.MemoryStream
  $ds.CopyTo($out)
  $ds.Close(); $ms.Close()
  return $out.ToArray()
}
function Sha1Hex([byte[]]$data) {
  $sha = [System.Security.Cryptography.SHA1]::Create()
  $h = $sha.ComputeHash($data)
  return (($h | ForEach-Object { $_.ToString('x2') }) -join '')
}
# git blob hash of a file
function GitBlobHash([string]$file) {
  $content = [System.IO.File]::ReadAllBytes($file)
  $prefix = [System.Text.Encoding]::ASCII.GetBytes("blob $($content.Length)`0")
  $all = New-Object byte[] ($prefix.Length + $content.Length)
  [Array]::Copy($prefix, 0, $all, 0, $prefix.Length)
  [Array]::Copy($content, 0, $all, $prefix.Length, $content.Length)
  return Sha1Hex $all
}
foreach ($f in @('workspace\electron\main.js','workspace\electron\preload.cjs','workspace\forge.config.cjs','workspace\package.json')) {
  Write-Output ("$f -> " + (GitBlobHash $f))
}"}

