function Get-BlobBody([string]$hash) {
  $dir = $hash.Substring(0,2); $file = $hash.Substring(2)
  $p = Join-Path (Join-Path 'workspace\.git\objects' $dir) $file
  if (-not (Test-Path $p)) { return $null }
  $raw = Inflate-GitBytes $p
  $nul = [Array]::IndexOf($raw, [byte]0x00, 0)
  $body = New-Object byte[] ($raw.Length - $nul - 1)
  [Array]::Copy($raw, $nul + 1, $body, 0, $body.Length)
  return [System.Text.Encoding]::UTF8.GetString($body)
}
function Show-Diff([string]$rel, [string]$hash) {
  $headBody = Get-BlobBody $hash
  $curBody = [System.IO.File]::ReadAllText((Join-Path (Get-Location) ("workspace\" + $rel)))
  $hl = ($headBody -replace "`r`n", "`n") -split "`n"
  $cl = ($curBody -replace "`r`n", "`n") -split "`n"
  Write-Output "===== $rel ====="
  $d = Compare-Object $hl $cl
  $d | Select-Object -First 40 | ForEach-Object { $_.SideIndicator + ' ' + $_.InputObject }
}
